from pathlib import Path
import subprocess,json,datetime
r=Path('C:/.projects/venus');out=r/'.artifacts/p05-a13-owned-cpu-profile01';before=json.loads((out/'inspect-before.json').read_text());cid=before['id']
q=subprocess.run(['docker','inspect',cid],capture_output=True,text=True,encoding='utf-8',timeout=15);assert q.returncode==0;x=json.loads(q.stdout)[0];assert x['Id']==cid and x['Image']==before['image'] and x['Config']['Labels']['com.docker.compose.project']==before['project'] and x['Config']['Labels']['com.docker.compose.service']=='app' and x['State']['Running']
js="""import fs from 'node:fs';import pg from 'pg';import{setTimeout as delay}from'node:timers/promises';
const c=new pg.Client({host:process.env.DB_HOST,port:5432,user:'venus',database:'venus',password:fs.readFileSync(process.env.DB_PASSWORD_FILE,'utf8').trim(),connectionTimeoutMillis:1000,query_timeout:2000});const rows=[];
try{await c.connect();for(let i=0;i<3;i++){const at=new Date().toISOString(),started=performance.now(),r=await c.query("SELECT state,wait_event_type,wait_event,count(*)::int AS connections FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() GROUP BY state,wait_event_type,wait_event ORDER BY state,wait_event_type,wait_event");rows.push({at,duration_ms:Math.round((performance.now()-started)*1000)/1000,groups:r.rows});if(i<2)await delay(1000);}console.log(JSON.stringify({scope:'THREE_READONLY_NATIVE_PG_WAIT_CLASS_SNAPSHOTS_NO_QUERY_TEXT_OR_VALUES',rows}));}catch(e){console.log(JSON.stringify({status:'FAIL',code:typeof e.code==='string'&&/^[A-Z0-9_]{1,32}$/.test(e.code)?e.code:'UNKNOWN',rows}));process.exitCode=1;}finally{await c.end();}
"""
p=subprocess.run(['docker','exec','-i',cid,'node','--input-type=module'],input=js,capture_output=True,text=True,encoding='utf-8',timeout=20);assert len(p.stdout.encode())<65536;(out/'pg-waits01.json').write_text(p.stdout,encoding='utf-8');(out/'pg-waits01-stderr.txt').write_text(p.stderr,encoding='utf-8');(out/'pg-waits01-receipt.json').write_text(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'exit':p.returncode,'project':before['project'],'owner_checked':True,'statements':'THREE_PG_STAT_ACTIVITY_AGGREGATE_SELECTS_ONLY','native_probe_already_instrumented':True,'APP_SQL_clock_rates_flags_unchanged':True},indent=2)+'\n',encoding='utf-8');print(p.stdout);raise SystemExit(p.returncode)
